        if ((bucket_name.len > 0)) {
            _ = try writer.print(comptime (Output.prettyFmt(" (<green>\"{s}/{s}\"<r>)<r> {{", enable_ansi_colors)), .{ bucket_name, s3.path() });
        } else {
